#include <iostream>
#include <vector>

using Matrix = std::vector<std::vector<int>>;

Matrix multiply(const Matrix& A, const Matrix& B, int n) {
    Matrix C(n, std::vector<int>(n, 0));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            for (int k = 0; k < n; ++k) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }
    return C;
}

int main() {
    int n;
    if (!(std::cin >> n) || n <= 0) return 0;

    Matrix A(n, std::vector<int>(n));
    Matrix B(n, std::vector<int>(n));

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            std::cin >> A[i][j];

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            std::cin >> B[i][j];

    // Main diagonal sum of A
    int diag_sum = 0;
    for (int i = 0; i < n; ++i) {
        diag_sum += A[i][i];
    }
    std::cout << "DiagSumA: " << diag_sum << "\n";

    // A * B
    Matrix AB = multiply(A, B, n);
    std::cout << "AB[0][0]: " << AB[0][0] << "\n";

    // A^2 - B^2
    Matrix A2 = multiply(A, A, n);
    Matrix B2 = multiply(B, B, n);
    std::cout << "(A^2-B^2)[0][0]: " << (A2[0][0] - B2[0][0]) << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <algorithm>
#include <cctype>
#include <map>

int main() {
    std::string s;
    if (!std::getline(std::cin, s)) return 0;

    // 1. Case-insensitive frequency count
    std::map<char, int> freq;
    for (unsigned char ch : s) {
        freq[std::tolower(ch)]++;
    }

    // 2. Erase-remove idiom: remove '-' and spaces for demonstration
    std::string cleaned = s;
    cleaned.erase(
        std::remove_if(cleaned.begin(), cleaned.end(), [](unsigned char c) {
            return c == '-' || c == ' ';
        }),
        cleaned.end()
    );

    // 3. Uppercase conversion
    std::string upper_cleaned = cleaned;
    std::transform(upper_cleaned.begin(), upper_cleaned.end(), upper_cleaned.begin(),
                   [](unsigned char c) { return std::toupper(c); });

    std::cout << "CleanedUpper: " << upper_cleaned << "\n";
    std::cout << "Count of 'a': " << freq['a'] << "\n";
    return 0;
}
